@pytest.mark.parametrize("with_data", [False, True])
def test_reset_index_coord_names(self, with_data) -> None:
    ds = Dataset(
        {"value": ("x", [4, 5, 6])} if with_data else {},
        coords={"a": ("x", [1, 2, 3]), "b": ("x", ["a", "b", "c"])},
    )
    indexed = ds.set_index(z=["a", "b"])
    actual = indexed.reset_index("z", drop=True)
    expected = Dataset({"value": ("x", [4, 5, 6])}) if with_data else Dataset()

    assert actual._coord_names <= actual._variables.keys()
    assert_identical(actual, expected)
    assert len(actual.data_vars) == int(with_data)
    assert repr(actual) == repr(expected)
    assert set(indexed.coords) == {"z", "a", "b"}

